style.css:
@-moz-document domain("koobits.com") {
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: url("https://chat.openai.com/file/file-1fLHu61fGKN9AG25rcm4HH") no-repeat center center fixed;
    background-size: cover;
    opacity: 0.85;
    z-index: -1;
    animation: floaty 30s ease-in-out infinite;
  }

  @keyframes floaty {
    0% {
      transform: scale(1) translateY(0);
    }
    50% {
      transform: scale(1.05) translateY(-10px);
    }
    100% {
      transform: scale(1) translateY(0);
    }
  }

  body {
    background: transparent !important;
  }
}
